/* --- MASTER AESTHETIC --- */

html, body.tc-body, .tc-page-container {
  background-color: #020617 !important;
  background-image: 
      radial-gradient(at 0% 0%, hsla(280,50%,20%,1) 0, transparent 80%), 
      radial-gradient(at 100% 0%, hsla(340,60%,24%,1) 0, transparent 80%),
      radial-gradient(at 50% 100%, hsla(210,50%,28%,1) 0, transparent 80%) !important;
  background-attachment: fixed !important;
  color: #a6adbb !important;
  font-family: 'Inter', sans-serif !important;
  font-size: 12px !important;
  line-height: 20px !important;
  word-wrap: break-word !important;
  fill: #FFFFFF !important;
}

.tc-page-container {
  margin: 0 !important; 
  padding-top: 34px !important;
  min-height: 100vh !important;
  display: flex !important;
  flex-direction: column !important;
  background: transparent !important;
}

/* Story River - WIDER LAYOUT (1600px Max) */
.tc-story-river {
  padding: 0 10px !important;
  width: 98% !important;
  max-width: 1900px !important;
  margin: 0 auto !important;
  position: relative !important; 
  z-index: 10 !important; 
  box-sizing: border-box !important;
}

@media (min-width: 1000px) {
  .tc-story-river {
    position: relative !important;
    left: 0px !important;
    top: 0px !important;
    padding: 8px 16px !important;
  }
}
/* --- STORY BACKDROP ALIGNMENT FIX --- */
.story-backdrop {
  text-align: left !important;
}

.story-backdrop td {
  text-align: left !important;
}

.story-backdrop td[align="right"] {
  text-align: left !important;
}

/* Story backdrop image cell sizing */
.story-backdrop td:first-child {
  width: 1% !important;
  white-space: nowrap !important;
  padding-right: 0.35rem !important;
  padding-left: 0.35rem !important;
}

.story-backdrop td:first-child img {
  display: inline-block !important;
  width: auto !important;
  height: auto !important;
  max-width: none !important;
}

/* Story backdrop table tweaks */
.story-backdrop table {
  font-weight: 600 !important;
}

.story-backdrop th,
.story-backdrop td {
  padding: 0.45rem 0.75rem !important;
}

.story-backdrop tbody tr:hover td,
.story-backdrop .table-hover tbody tr:hover td {
  background-color: transparent !important;
}

.story-backdrop td,
.story-backdrop th {
  border-bottom: 1px solid rgba(255, 255, 255, 0.03) !important;
}

/* --- NAVBAR FINAL (Static, No Hover) --- */
.ts-glass-header {
    position: fixed !important; 
    top: 0; 
    left: 0; 
    right: 0; 
    height: 32px; 
    background: rgba(15, 23, 42, 0.05) !important; 
    backdrop-filter: blur(25px); 
    -webkit-backdrop-filter: blur(25px); 
    border: none !important;
    border-top: none !important;
    border-bottom: none !important;
    border-left: none !important;
    border-right: none !important;
    z-index: 5000 !important;
    display: flex; 
    align-items: center; 
    justify-content: flex-start !important;
    padding: 0 1rem; 
    gap: 1rem;
}

.ts-header-link {
    text-decoration: none !important; 
    background: transparent !important;
    color: rgba(255,255,255,0.7) !important;
    display: flex; 
    align-items: center; 
    pointer-events: auto;
}

.ts-glass-header-title {
    font-size: 0.75rem; 
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.ts-header-brand {
    color: #ffffff !important;
    font-weight: 700;
}

.ts-header-subtitle {
    color: #2dd4bf !important;
}


.ts-header-buttons {
    margin-left: auto;
    display: flex;
    gap: 0.5rem;
    align-items: center;
    pointer-events: auto;
}

.ts-glass-logo { width: 1.1rem; height: 1.1rem; background: rgba(20, 184, 166, 0.2); color: #2dd4bf; border: 1px solid rgba(45, 212, 191, 0.2); border-radius: 3px; display: flex; align-items: center; justify-content: center; font-size: 0.55rem; font-weight: 800; }

/* --- TABLE STYLING --- */
table {
    width: 100%;
    margin: 1rem 0 !important;
    border-collapse: collapse !important;
    border-spacing: 0 !important;
    font-size: 0.85rem !important;
    color: #a6adbb !important;
    border: none !important;
    border-top: none !important;
    border-bottom: none !important;
    border-left: none !important;
    border-right: none !important;
    background: transparent !important;
}

th {
    background-color: transparent !important;
    color: #ffffff !important;
    text-transform: uppercase;
    font-weight: 700 !important;
    font-size: 0.75rem !important;
    padding: 1rem !important;
    border: none !important;
    border-top: none !important;
    border-left: none !important;
    border-right: none !important;
    border-bottom: 1px solid rgba(255,255,255,0.1) !important;
    text-align: left;
    white-space: nowrap;
}

td {
    padding: 0.75rem 1rem !important;
    border: none !important;
    border-top: none !important;
    border-left: none !important;
    border-right: none !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.03) !important;
    background-color: transparent !important;
    transition: background-color 0.1s;
    vertical-align: middle !important;
}


/* Table row borders */
.tc-tiddler-body table tbody tr td,
.tc-tab-content table tbody tr td {
  border-bottom: 1px solid rgba(255, 255, 255, 0.08) !important;
}
/* Keep icon + text on one line in table cells */
td img,
td svg {
    display: inline-block !important;
    vertical-align: middle !important;
}

td img + br,
td svg + br {
    display: none !important;
}

td img + *,
td svg + * {
    display: inline !important;
    vertical-align: middle !important;
    margin-left: 0.35rem !important;
}

td * + img,
td * + svg {
    display: inline-block !important;
    vertical-align: middle !important;
    margin-left: 0.35rem !important;
}

td br,
th br {
    display: none !important;
}

/* Override old_style.css borders - aggressive */
table, table th, table td, table tr {
    border-top: none !important;
    border-left: none !important;
    border-right: none !important;
}

/* Remove any remaining table borders */
.tc-tab-content table,
.tc-tab-content table th,
.tc-tab-content table td,
.tc-tab-content table tr {
    border-top: none !important;
    border-left: none !important;
    border-right: none !important;
}

/* Tailwind border override */
.border,
.flex-col.border,
div.border,
.tc-tab-content .border {
    border: none !important;
    border-top: none !important;
    border-bottom: none !important;
    border-left: none !important;
    border-right: none !important;
}

/* Column controls wrapping fix */
.col-controls,
div[class*="col-controls"],
.tc-tab-content .col-controls {
    display: flex !important;
    flex-wrap: wrap !important;
    gap: 0.5rem !important;
    width: 100% !important;
    max-width: 100% !important;
    overflow: visible !important;
}

/* Comprehensive overflow prevention */
.tc-tiddler-body,
.tc-tab-content,
.tc-tiddler-frame {
    overflow-x: auto !important;
    overflow-y: visible !important;
    max-width: 100% !important;
    box-sizing: border-box !important;
}

/* Ensure all child elements respect container width */
.tc-tiddler-body > *,
.tc-tab-content > * {
    max-width: 100% !important;
    box-sizing: border-box !important;
}

/* Force flex containers to wrap and not overflow */
.tc-tiddler-body div,
.tc-tab-content div {
    max-width: 100% !important;
    overflow-wrap: break-word !important;
    word-wrap: break-word !important;
}

/* Flex items should shrink if needed */
.tc-tiddler-body [class*="flex"],
.tc-tab-content [class*="flex"] {
    flex-shrink: 1 !important;
    min-width: 0 !important;
}

/* Icon sizing in headers only */
th img, th svg {
    width: 20px !important;
    height: 20px !important;
    max-width: 20px !important;
    max-height: 20px !important;
    display: inline-block !important;
    vertical-align: middle !important;
    object-fit: contain !important;
}

/* Special handling for header icons wrapped in links or spans */
th a img, th span img, th a svg, th span svg {
    width: 20px !important;
    height: 20px !important;
    max-width: 20px !important;
    max-height: 20px !important;
}


/* Log Summary tables: no row borders */
[data-tiddler-title$="-Log-Summary"] .tc-tiddler-body tbody tr td {
  border-bottom: none !important;
}
/* Hover effect */
/* Log Summary tables: font size */
[data-tiddler-title$="-Log-Summary"] .tc-tiddler-body table {
  font-size: 0.85rem !important;
}

tbody tr:hover td,
.table-hover tbody tr:hover,
.table-hover tbody tr:hover td {
    background-color: rgba(255, 255, 255, 0.008) !important;
    color: #a6adbb !important;
}

/* Commander Summary Table - Compact & Left Aligned */
.tc-tiddler-frame table:not(.tc-tab-content *) {
    width: auto !important;
    max-width: 60% !important;
    font-size: 0.7rem !important;
}

.tc-tiddler-frame table:not(.tc-tab-content *) th {
    font-size: 0.65rem !important;
    padding: 0.6rem 0.8rem !important;
}

.tc-tiddler-frame table:not(.tc-tab-content *) td {
    font-size: 0.85rem !important;
    padding: 0.5rem 0.8rem !important;
}

/* Icon sizing for compact summary table headers */
.tc-tiddler-frame table:not(.tc-tab-content *) img,
.tc-tiddler-frame table:not(.tc-tab-content *) svg {
    width: 20px !important;
    height: 20px !important;
    min-width: 20px !important;
    min-height: 20px !important;
    max-width: 20px !important;
    max-height: 20px !important;
    display: inline-block !important;
    vertical-align: middle !important;
    object-fit: contain !important;
}

.tc-tiddler-frame table:not(.tc-tab-content *) th img,
.tc-tiddler-frame table:not(.tc-tab-content *) th svg,
.tc-tiddler-frame table:not(.tc-tab-content *) td img,
.tc-tiddler-frame table:not(.tc-tab-content *) td svg {
    width: 20px !important;
    height: 20px !important;
    min-width: 20px !important;
    min-height: 20px !important;
    max-width: 20px !important;
    max-height: 20px !important;
    display: inline-block !important;
    vertical-align: middle !important;
    object-fit: contain !important;
}

/* Override: Tab content tables are full width */
.tc-tiddler-frame .tc-tab-content table {
    width: 100% !important;
    max-width: 100% !important;
    font-size: 0.85rem !important;
}

.tc-tiddler-frame .tc-tab-content table th {
    font-size: 0.75rem !important;
    padding: 1rem !important;
}

.tc-tiddler-frame .tc-tab-content table td {
    font-size: 0.85rem !important;
    padding: 0.75rem 1rem !important;
}

/* --- TAG STYLING --- */
span.tc-tag-label,
button.tc-tag-label,
a.tc-tag-label {
    color: #2dd4bf !important;
    font-weight: 600 !important;
    font-size: 0.7rem !important;
    text-transform: uppercase;
    line-height: 1.2em;
    white-space: break-spaces;
    background: rgba(45, 212, 191, 0.12) !important;
    border: 1px solid rgba(45, 212, 191, 0.22) !important;
    border-radius: 6px !important;
    padding: 0.18rem 0.5rem !important;
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    text-decoration: none !important;
    box-shadow: 0 0 8px rgba(45, 212, 191, 0.15), 
                0 0 16px rgba(45, 212, 191, 0.08) !important;
    transition: all 0.2s ease;
}

span.tc-tag-label:hover,
button.tc-tag-label:hover,
a.tc-tag-label:hover {
    background: rgba(45, 212, 191, 0.18) !important;
    color: #7ff3e5 !important;
    box-shadow: 0 0 12px rgba(45, 212, 191, 0.2), 
                0 0 24px rgba(45, 212, 191, 0.12) !important;
}

.tc-btn-invisible {
    cursor: pointer;
    color: #FFFFFF;
    fill: #FFFFFF;
}

/* --- LINK STYLING --- */
a, a:link {
    color: #2dd4bf !important;
    text-decoration: none !important;
    transition: color 0.2s;
}

a:visited {
    color: #14b8a6 !important;
}

a:hover {
    color: #5eead4 !important;
    text-decoration: underline !important;
}

a:active {
    color: #2dd4bf !important;
}

/* --- RADIO BUTTON STYLING --- */
/* Container for radio button groups */
.tc-tab-content > p,
.tc-tiddler-body > p {
    display: flex !important;
    flex-wrap: wrap !important;
    gap: 0.3rem !important;
    align-items: center !important;
}

/* Individual radio button labels */
.tc-tab-content label,
.tc-tiddler-body label {
    display: inline-flex !important;
    align-items: center !important;
    gap: 0.4rem !important;
    padding: 0.5rem 0.6rem !important;
    margin: 0 !important;
    background: rgba(45, 212, 191, 0.12) !important;
    border: 1px solid rgba(45, 212, 191, 0.22) !important;
    border-radius: 6px !important;
    box-shadow: 0 0 8px rgba(45, 212, 191, 0.15), 
                0 0 16px rgba(45, 212, 191, 0.08) !important;
    transition: all 0.2s ease !important;
    cursor: pointer !important;
    white-space: nowrap !important;
    line-height: 1 !important;
}

.tc-tab-content label:hover,
.tc-tiddler-body label:hover {
    background: rgba(45, 212, 191, 0.18) !important;
    box-shadow: 0 0 12px rgba(45, 212, 191, 0.2), 
                0 0 24px rgba(45, 212, 191, 0.12) !important;
}

/* Radio buttons themselves */
input[type="radio"] {
    appearance: none !important;
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    width: 14px !important;
    height: 14px !important;
    min-width: 14px !important;
    min-height: 14px !important;
    border: 2px solid rgba(45, 212, 191, 0.5) !important;
    border-radius: 3px !important;
    background: rgba(15, 23, 42, 0.6) !important;
    cursor: pointer !important;
    position: relative !important;
    margin: 0 !important;
    padding: 0 !important;
    transition: all 0.2s ease !important;
    flex-shrink: 0 !important;
}

input[type="radio"]:hover {
    border-color: rgba(45, 212, 191, 0.8) !important;
    background: rgba(45, 212, 191, 0.15) !important;
}

input[type="radio"]:checked {
    background: rgba(45, 212, 191, 0.3) !important;
    border-color: #2dd4bf !important;
}

input[type="radio"]:checked::after {
    content: '' !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    width: 6px !important;
    height: 6px !important;
    background: #2dd4bf !important;
    border-radius: 1px !important;
    box-shadow: 0 0 4px rgba(45, 212, 191, 0.8) !important;
}

/* Icons and images inside labels */
label img,
label svg {
    width: 20px !important;
    height: 20px !important;
    flex-shrink: 0 !important;
    vertical-align: middle !important;
    object-fit: contain !important;
    display: inline-block !important;
}

/* Ensure all content in labels stays inline */
label * {
    display: inline !important;
    vertical-align: middle !important;
}

/* Exception for radio button which needs specific display */
label input[type="radio"] {
    display: inline-block !important;
}

/* --- UNCHECK TO HIDE CONTROLS STYLING --- */

/* --- RADIO ROW SPACING --- */
.tc-tab-content > p + p,
.tc-tiddler-body > p + p {
    padding-top: 0.4rem !important;
    margin-top: 0.4rem !important;
}

.tc-tab-content .col-controls,
.tc-tiddler-body .col-controls {
    display: flex !important;
    flex-wrap: wrap !important;
    gap: 0.4rem !important;
    align-items: center !important;
    padding: 0.75rem 0.9rem !important;
    margin: 0.6rem 0 1rem 0 !important;
    background: rgba(21, 25, 30, 0.55) !important;
    border: 1px solid rgba(255, 255, 255, 0.06) !important;
    border-radius: 12px !important;
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255,255,255,0.03) !important;
    backdrop-filter: blur(24px) saturate(120%) !important;
    -webkit-backdrop-filter: blur(24px) saturate(120%) !important;
}

.tc-tab-content .col-controls label,
.tc-tiddler-body .col-controls label {
    display: inline-flex !important;
    align-items: center !important;
    gap: 0.35rem !important;
    padding: 0.32rem 0.5rem !important;
    margin: 0 !important;
    background: rgba(45, 212, 191, 0.08) !important;
    border: 1px solid rgba(45, 212, 191, 0.2) !important;
    border-radius: 8px !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.04) !important;
    transition: all 0.2s ease !important;
    cursor: pointer !important;
    white-space: nowrap !important;
    line-height: 1 !important;
}

.tc-tab-content .col-controls label:hover,
.tc-tiddler-body .col-controls label:hover {
    background: rgba(45, 212, 191, 0.14) !important;
    border-color: rgba(45, 212, 191, 0.35) !important;
}

.tc-tab-content .col-controls input[type="checkbox"],
.tc-tiddler-body .col-controls input[type="checkbox"] {
    appearance: none !important;
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    width: 14px !important;
    height: 14px !important;
    min-width: 14px !important;
    min-height: 14px !important;
    border: 1px solid rgba(45, 212, 191, 0.45) !important;
    border-radius: 4px !important;
    background: rgba(15, 23, 42, 0.6) !important;
    cursor: pointer !important;
    position: relative !important;
    margin: 0 !important;
    transition: all 0.2s ease !important;
}

.tc-tab-content .col-controls input[type="checkbox"]:checked,
.tc-tiddler-body .col-controls input[type="checkbox"]:checked {
    background: rgba(45, 212, 191, 0.28) !important;
    border-color: #2dd4bf !important;
}

.tc-tab-content .col-controls input[type="checkbox"]:checked::after,
.tc-tiddler-body .col-controls input[type="checkbox"]:checked::after {
    content: '✓' !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    color: #2dd4bf !important;
    font-size: 10px !important;
    font-weight: bold !important;
}


/* --- FOOTER LAYOUT FIX --- */
.tc-story-frontdrop {
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

.tc-story-river {
    flex: 1 0 auto;
}

.ts-footer {
    margin-top: auto;
}


/* --- FOOTER HIDE --- */
.story-frontdrop,
.tc-story-frontdrop,
.ts-footer,
.tc-footer {
    display: none !important;
}

/* --- FOOTER --- */
.tc-footer {
    position: relative;
    z-index: 20;
    margin-top: 24px;
    padding-bottom: 16px;
}

.tc-page-container {
    padding-bottom: 60px !important;
}


.tc-story-frontdrop {
    position: relative;
    z-index: 1;
    padding-bottom: 48px;
}

.ts-footer {
    position: relative;
    z-index: 30;
    margin-top: 24px;
    padding-bottom: 16px;
}

/* --- TABS (Glassy) --- */
.tc-tab-buttons {
    padding-bottom: 0 !important;
    margin-bottom: 0.9rem !important;
    border-bottom: 1px solid rgba(255,255,255,0.05);
    display: flex;
    gap: 0.3rem;
    flex-wrap: wrap;
}
.tc-tab-buttons button {
    background: transparent !important;
    border: none !important;
    border-bottom: 2px solid transparent !important;
    color: rgba(226, 232, 240, 0.55) !important;
    font-weight: 700 !important;
    padding: 0.35rem 0.5rem !important;
    font-size: 0.68rem !important;
    letter-spacing: 0.02em;
    transition: all 0.2s;
}
.tc-tab-buttons button.tc-tab-selected {
    color: #2dd4bf !important;
    border-bottom-color: #2dd4bf !important;
    background: linear-gradient(to top, rgba(45, 212, 191, 0.12), transparent) !important;
}

/* --- HIDE CORE UI --- */
.tc-site-title, .tc-site-subtitle, .tc-page-controls, .tc-topbar, .tc-sidebar-header, .tc-banner, .tc-header, [class^="tc-topbar"] { display: none !important; visibility: hidden !important; }

/* Toast notifications (saving/saved) */
.tc-notification {
  background: rgba(15, 23, 42, 0.35) !important;
  border: 1px solid rgba(255, 255, 255, 0.1) !important;
  border-radius: 14px !important;
  padding: 0.85rem 1.1rem !important;
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.5) !important;
  backdrop-filter: blur(26px) saturate(120%) !important;
  -webkit-backdrop-filter: blur(26px) saturate(120%) !important;
  letter-spacing: 0.01em !important;
}
.tc-notification .tc-title {
  color: #f8fafc !important;
  font-weight: 700 !important;
  margin-bottom: 0.2rem !important;
}
.tc-notification .tc-body,
.tc-notification a {
  color: #cbd5f5 !important;
}

/* Tooltip glassmorphism */
.tooltip::after,
.tc-tooltip::after {
  width: max-content !important;
  max-width: 60vw !important;
  white-space: nowrap !important;
  padding: 0.35rem 0.6rem !important;
  background: rgba(15, 23, 42, 0.35) !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  border-radius: 8px !important;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35) !important;
  backdrop-filter: blur(22px) saturate(120%) !important;
  -webkit-backdrop-filter: blur(22px) saturate(120%) !important;
  color: #e2e8f0 !important;
  font-weight: 600 !important;
  letter-spacing: 0.01em !important;
}
.tooltip::before,
.tc-tooltip::before {
  border-bottom-color: rgba(15, 23, 42, 0.35) !important;
}

/* Tooltip glassmorphism (xtooltip) */
.xtooltip {
  position: relative !important;
}
.xtooltip .xtooltiptext {
  width: max-content !important;
  max-width: 60vw !important;
  white-space: nowrap !important;
  padding: 0.35rem 0.6rem !important;
  background: rgba(15, 23, 42, 0.05) !important;
  color: #e2e8f0 !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  border-radius: 8px !important;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35) !important;
  backdrop-filter: blur(25px) saturate(120%) !important;
  -webkit-backdrop-filter: blur(25px) saturate(120%) !important;
  position: absolute !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  top: calc(100% + 6px) !important;
  z-index: 9999 !important;
  pointer-events: none !important;
  overflow: hidden !important;
  letter-spacing: 0.01em !important;
}
/* --- POPUPS --- */
.tc-notification, .tc-popup, .tc-drop-down, .tc-alerts, .tc-modal-wrapper { z-index: 6000 !important; }
.tc-notification, .tc-alerts { top: 40px !important; }

/* Popup dropdowns: glass + inline icon/text */
.tc-drop-down {
  background: rgba(15, 23, 42, 0.25) !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  border-radius: 10px !important;
  padding: 0.35rem !important;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.45) !important;
  backdrop-filter: blur(25px) saturate(120%) !important;
  -webkit-backdrop-filter: blur(25px) saturate(120%) !important;
}

.tc-drop-down .tc-btn-invisible {
  display: flex !important;
  align-items: center !important;
  gap: 0.4rem !important;
  white-space: nowrap !important;
  width: 100% !important;
  justify-content: flex-start !important;
}
.tc-drop-down .tc-btn-text {
  display: inline !important;
  white-space: nowrap !important;
}
.tc-drop-down svg {
  display: inline-block !important;
  vertical-align: middle !important;
}
.tc-drop-down .tc-btn-invisible {
  color: #a6adbb !important;
  opacity: 1 !important;
}
.tc-drop-down:hover .tc-btn-invisible {
  color: #a6adbb !important;
  opacity: 1 !important;
}
.tc-drop-down .tc-btn-invisible:hover,
.tc-drop-down .tc-btn-invisible:focus,
.tc-drop-down .tc-btn-invisible:active {
  background: rgba(255, 255, 255, 0.03) !important;
  box-shadow: none !important;
  color: #a6adbb !important;
  opacity: 1 !important;
}
.tc-drop-down .tc-btn-invisible:hover *,
.tc-drop-down .tc-btn-invisible:focus *,
.tc-drop-down .tc-btn-invisible:active * {
  opacity: 1 !important;
  filter: none !important;
}
.tc-drop-down .tc-btn-invisible:hover svg,
.tc-drop-down .tc-btn-invisible:focus svg,
.tc-drop-down .tc-btn-invisible:active svg {
  opacity: 1 !important;
  filter: none !important;
  fill: currentColor !important;
  stroke: currentColor !important;
}

/* --- ICONS --- */
.ts-icon-btn { background: transparent !important; border: none !important; padding: 4px !important; cursor: pointer !important; display: flex; align-items: center; justify-content: center; transition: all 0.2s; }
.ts-icon-btn svg { width: 14px !important; height: 14px !important; stroke: rgba(255,255,255,0.3) !important; stroke-width: 2.2 !important; fill: none !important; }
.ts-icon-btn:hover svg { stroke: #2dd4bf !important; transform: scale(1.1); }
.ts-save-dirty { background: rgba(239, 68, 68, 0.1) !important; border-radius: 4px !important; }
.ts-save-dirty svg { stroke: #ef4444 !important; fill: none !important; filter: drop-shadow(0 0 6px rgba(239,68,68,0.5)) !important; animation: pulse 2s ease-in-out infinite !important; }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.7; } }

/* --- FOOTER --- */
.story-backdrop,
.tc-story-river + * {
    position: relative !important;
    z-index: 1 !important;
}

/* --- TIDDLER GLASS --- */
.tc-tiddler-frame {
  background: rgba(21, 25, 30, 0.70) !important;
  backdrop-filter: blur(40px) !important;
  -webkit-backdrop-filter: blur(40px) !important;
  border: none !important;
  border-radius: 16px !important;
  box-shadow: 0 20px 50px -10px rgba(0, 0, 0, 0.6) !important;
  margin-bottom: 2rem !important;
  padding: 1.5rem 2rem !important;
}
.tc-title {
  color: #f8fafc !important;
  font-weight: 900 !important;
  font-size: 1.2rem !important;
  letter-spacing: -0.02em;
  text-align: left !important;
  margin: 0 0 0.5rem 0 !important;
  padding: 0 !important;
  line-height: 1.2 !important;
}
.tc-tiddler-body {
  text-align: left !important;
}
.tc-tiddler-controls {
  opacity: 0.65;
}
.tc-tiddler-controls:hover {
  opacity: 0.95;
}

/* Media query for wider tiddler frames */
@media (min-width: 1000px) {
  .tc-tiddler-frame {
    width: calc(100% - 84px) !important;
  }
}


/* Import-only compact spacing */
.tc-import-table td,
.tc-import-table th {
  padding: 0 !important;
  line-height: 1.05 !important;
}

.tc-import-table td > .tc-reveal,
.tc-import-table td > .tc-flex,
.tc-import-table td > .tc-checkbox {
  margin: 0 !important;
  padding: 0 !important;
}

.tc-import-table .tc-btn-invisible {
  padding: 0.05rem 0.15rem !important;
  margin: 0 !important;
  line-height: 1.05 !important;
}

.tc-import-table .tc-checkbox {
  padding: 0 !important;
  margin: 0 !important;
}

.tc-import-table .tc-flex {
  gap: 0.15rem !important;
}

.tc-import-table .tc-image-button {
  width: 14px !important;
  height: 14px !important;
}

/* Import-only warning rows */
.tc-import-table .tc-row-warning {
  background: rgba(45, 212, 191, 0.08) !important;
  border: 1px solid rgba(45, 212, 191, 0.12) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04), 0 6px 18px rgba(0, 0, 0, 0.2) !important;
  backdrop-filter: blur(16px) saturate(130%) !important;
  -webkit-backdrop-filter: blur(16px) saturate(130%) !important;
}

/* Import-only checkbox cleanup */
.tc-import-table .tc-checkbox,
.tc-import-table .tc-checkbox * {
  box-shadow: none !important;
  outline: none !important;
}
.tc-import-table input[type="checkbox"] {
  box-shadow: none !important;
  outline: none !important;
}
